SHELL_TABS = ('PROJECT', 'IMPORT', 'TRANSFORM', 'ALIGN', 'REVIEW', 'SURFACE', 'EXPORT')
SHELL_TAB_LABELS = MappingProxyType({'PROJECT': 'Proje', 'IMPORT': 'Ice aktar', 'TRANSFORM': 'Donustur', 'ALIGN': 'Hizala', 'REVIEW': 'Gorunum', 'SURFACE': 'Yuzey', 'EXPORT': 'Cikti'})
