def _font_stack(candidates: tuple[str, ...], generic: str) -> str:
    del generic
    return f'"{candidates[-1]}"'

def skin_c_stylesheet() -> str:
    sans = _font_stack(FONT_SANS_CANDIDATES, 'sans-serif')
    mono = _font_stack(FONT_MONO_CANDIDATES, 'monospace')
    color = SKIN_C_DARK
